def summarize(lines: list[str]) -> dict:
    by_status: dict[int, int] = {}
    path_stats: dict[str, list[float | int]] = {}
    total = 0
    server_errors = 0

    for line in lines:
        fields = line.split()
        if len(fields) < 5:
            continue

        path = fields[2]

        try:
            status = int(fields[3])

            response_time = fields[4]
            if not response_time.endswith("ms"):
                continue
            elapsed_ms = float(response_time[:-2])

            if elapsed_ms < 0:
                continue
        except (ValueError, TypeError):
            continue

        total += 1
        by_status[status] = by_status.get(status, 0) + 1

        if 500 <= status <= 599:
            server_errors += 1

        if path not in path_stats:
            path_stats[path] = [0.0, 0]
        path_stats[path][0] += elapsed_ms
        path_stats[path][1] += 1

    slowest_path = None
    if path_stats:
        slowest_path = max(
            sorted(path_stats),
            key=lambda path: path_stats[path][0] / path_stats[path][1],
        )

    return {
        "total": total,
        "by_status": by_status,
        "slowest_path": slowest_path,
        "error_rate": round(server_errors / total, 4) if total else 0.0,
    }
