/**
 * 배열을 keyFn(item)의 반환값 기준으로 그룹화한다.
 *
 * @param {Array} arr - 그룹화할 배열
 * @param {Function} keyFn - 각 아이템에서 그룹 키를 추출하는 함수 (item, index) => key
 * @returns {Object} { key: [items...] } 형태의 객체
 *
 * @example
 * groupBy([1.1, 1.9, 2.3], Math.floor);
 * // => { '1': [1.1, 1.9], '2': [2.3] }
 *
 * groupBy(
 *   [{ type: 'a', v: 1 }, { type: 'b', v: 2 }, { type: 'a', v: 3 }],
 *   (item) => item.type
 * );
 * // => { a: [{ type: 'a', v: 1 }, { type: 'a', v: 3 }], b: [{ type: 'b', v: 2 }] }
 */
function groupBy(arr, keyFn) {
  if (!Array.isArray(arr)) {
    throw new TypeError('groupBy: 첫 번째 인자는 배열이어야 합니다.');
  }
  if (typeof keyFn !== 'function') {
    throw new TypeError('groupBy: 두 번째 인자는 함수여야 합니다.');
  }

  const result = Object.create(null);

  for (let i = 0; i < arr.length; i++) {
    const key = String(keyFn(arr[i], i));
    if (!result[key]) {
      result[key] = [];
    }
    result[key].push(arr[i]);
  }

  // Object.create(null) 결과를 일반 객체로 변환해 반환
  return Object.assign({}, result);
}

module.exports = { groupBy };
```

**사용 예시:**

```js
const { groupBy } = require('./groupBy');

const users = [
  { name: 'Kim', age: 20 },
  { name: 'Lee', age: 30 },
  { name: 'Park', age: 20 },
];

console.log(groupBy(users, (u) => u.age));
// { '20': [{name:'Kim',...}, {name:'Park',...}], '30': [{name:'Lee',...}] }
```

**구현 포인트:**
- `Object.create(null)`로 프로토타입 없는 객체를 사용해, 키가 `constructor`, `toString` 같은 값일 때 발생할 수 있는 프로토타입 충돌을 방지했습니다.
- 키는 `String()`으로 변환되므로 숫자, 불리언 등도 안전하게 키로 사용됩니다.
- `keyFn`에 두 번째 인자로 인덱스도 전달해 유연하게 쓸 수 있습니다.

