/**
 * 배열을 keyFn(item)의 반환값 기준으로 그룹핑합니다.
 *
 * @param {Array} arr - 그룹핑할 배열
 * @param {(item: any) => (string|number)} keyFn - 각 요소로부터 그룹 키를 만드는 함수
 * @returns {Object} { key: [items...] } 형태의 객체
 */
function groupBy(arr, keyFn) {
  if (!Array.isArray(arr)) {
    throw new TypeError('첫 번째 인자(arr)는 배열이어야 합니다.');
  }
  if (typeof keyFn !== 'function') {
    throw new TypeError('두 번째 인자(keyFn)는 함수여야 합니다.');
  }

  // 프로토타입 오염 방지를 위해 프로토타입 없는 객체 사용
  const result = Object.create(null);

  for (let i = 0; i < arr.length; i++) {
    const item = arr[i];
    const key = String(keyFn(item, i, arr));

    if (result[key] === undefined) {
      result[key] = [];
    }
    result[key].push(item);
  }

  return result;
}

module.exports = { groupBy };
