class Emitter {
  constructor() {
    this.events = new Map();
  }

  on(event, fn) {
    if (!this.events.has(event)) {
      this.events.set(event, []);
    }
    this.events.get(event).push(fn);
    return this;
  }

  off(event, fn) {
    if (!this.events.has(event)) return this;

    // fn이 없으면 해당 이벤트의 모든 리스너 제거
    if (!fn) {
      this.events.delete(event);
      return this;
    }

    const listeners = this.events.get(event);
    const index = listeners.indexOf(fn);
    if (index !== -1) {
      listeners.splice(index, 1);
    }

    if (listeners.length === 0) {
      this.events.delete(event);
    }

    return this;
  }

  once(event, fn) {
    const wrapper = (...args) => {
      this.off(event, wrapper);
      fn.apply(this, args);
    };
    // 원본 함수 참조 유지를 위해 wrapper에 원본 연결 (선택사항이지만 디버깅에 유리)
    wrapper.original = fn;
    return this.on(event, wrapper);
  }

  emit(event, ...args) {
    if (!this.events.has(event)) return 0;

    // 1. emit 중 off 호출 및 once 리스너의 안전한 처리를 위해 복사본(스냅샷) 순회
    const listeners = [...this.events.get(event)];

    for (const fn of listeners) {
      // 2. emit 도중 이미 제거된 리스너인지 확인 (이중 실행 방지)
      const currentListeners = this.events.get(event);
      if (currentListeners && !currentListeners.includes(fn)) {
        continue;
      }

      fn.apply(this, args);
    }

    return listeners.length;
  }
}

module.exports = { Emitter };
