const bus = new Emitter();

const h = (x) => console.log('on:', x);
bus.on('data', h).once('data', (x) => console.log('once:', x));

console.log(bus.emit('data', 1)); // on: 1 / once: 1 / → 2
console.log(bus.emit('data', 2)); // on: 2 / → 1 (once 제거됨)

bus.off('data', h);
console.log(bus.emit('data', 3)); // → 0
```

