      throw new TypeError('listener는 함수여야 합니다');
    }
    let list = this._events.get(event);
    if (!list) {
      list = [];
      this._events.set(event, list);
    }
    list.push(fn);
    return this;
  }

  /** 핸들러 제거. fn 생략 시 해당 이벤트 전체 제거 */
  off(event, fn) {
    const list = this._events.get(event);
    if (!list) return this;

    if (fn == null) {
      this._events.delete(event);
      return this;
    }

    // once 래퍼는 _origin으로 원본 함수와 매칭
    const idx = list.findIndex((l) => l === fn || l._origin === fn);
    if (idx !== -1) list.splice(idx, 1);
    if (list.length === 0) this._events.delete(event);
    return this;
  }

  /** 1회만 실행. 실행 "전"에 제거되어 재진입 emit에서도 중복 실행 없음 */
  once(event, fn) {
    if (typeof fn !== 'function') {
      throw new TypeError('listener는 함수여야 합니다');
    }
    const wrapper = (...args) => {
      this.off(event, wrapper); // 호출 전에 먼저 제거
      fn.apply(this, args);
    };
    wrapper._origin = fn; // off(event, 원본fn)으로도 제거 가능하게
    return this.on(event, wrapper);
  }

  /** 등록 순서대로 호출, 실제 호출된 리스너 수 반환 */
  emit(event, ...args) {
    const list = this._events.get(event);
    if (!list || list.length === 0) return 0;

    const snapshot = list.slice(); // 순회 중 on/off로 배열이 변해도 안전
    let called = 0;

    for (const fn of snapshot) {
      // emit 도중 off된 리스너는 건너뜀
      const current = this._events.get(event);
      if (!current || !current.includes(fn)) continue;
      fn.apply(this, args);
      called++;
    }
    return called;
  }
