```go
package pool

import "sync"

// ProcessAll: jobs의 각 정수에 fn을 적용한 결과를 '입력 순서대로' 반환.
// workers 개의 고루틴으로 병렬 처리. workers <= 0 이면 1로 취급.
func ProcessAll(jobs []int, workers int, fn func(int) int) []int {
	n := len(jobs)
	results := make([]int, n)
	if n == 0 {
		return results
	}

	if workers <= 0 {
		workers = 1
	}
	if workers > n {
		workers = n
	}

	// 인덱스를 전달해 각 워커가 자신의 슬롯(results[idx])에만 쓴다.
	// 서로 다른 인덱스에 쓰므로 데이터 레이스 없음.
	indexCh := make(chan int)

	var wg sync.WaitGroup
	wg.Add(workers)
	for w := 0; w < workers; w++ {
		go func() {
			defer wg.Done()
			for idx := range indexCh {
				results[idx] = fn(jobs[idx])
			}
		}()
	}

	for i := 0; i < n; i++ {
		indexCh <- i
	}
	close(indexCh)

	wg.Wait()
	return results
}
